//! A from-scratch implementation of the BLAKE3 hash function, including the
//! keyed and key-derivation modes, an extendable output reader, and a
//! multi-threaded subtree hashing path for large in-memory inputs.

pub const OUT_LEN: usize = 32;
pub const KEY_LEN: usize = 32;
pub const BLOCK_LEN: usize = 64;
pub const CHUNK_LEN: usize = 1024;

const CHUNK_START: u32 = 1 << 0;
const CHUNK_END: u32 = 1 << 1;
const PARENT: u32 = 1 << 2;
const ROOT: u32 = 1 << 3;
const KEYED_HASH: u32 = 1 << 4;
const DERIVE_KEY_CONTEXT: u32 = 1 << 5;
const DERIVE_KEY_MATERIAL: u32 = 1 << 6;

const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB,
    0x5BE0CD19,
];

const SCHEDULE: [[usize; 16]; 7] = build_schedule();

const fn build_schedule() -> [[usize; 16]; 7] {
    const PERM: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];
    let mut out = [[0usize; 16]; 7];
    let mut i = 0;
    while i < 16 {
        out[0][i] = i;
        i += 1;
    }
    let mut r = 1;
    while r < 7 {
        let mut j = 0;
        while j < 16 {
            out[r][j] = out[r - 1][PERM[j]];
            j += 1;
        }
        r += 1;
    }
    out
}

#[inline(always)]
fn g(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(x);
    s[d] = (s[d] ^ s[a]).rotate_right(16);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(12);
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(y);
    s[d] = (s[d] ^ s[a]).rotate_right(8);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(7);
}

#[inline(always)]
fn round(s: &mut [u32; 16], m: &[u32; 16], r: usize) {
    let sc = &SCHEDULE[r];
    g(s, 0, 4, 8, 12, m[sc[0]], m[sc[1]]);
    g(s, 1, 5, 9, 13, m[sc[2]], m[sc[3]]);
    g(s, 2, 6, 10, 14, m[sc[4]], m[sc[5]]);
    g(s, 3, 7, 11, 15, m[sc[6]], m[sc[7]]);
    g(s, 0, 5, 10, 15, m[sc[8]], m[sc[9]]);
    g(s, 1, 6, 11, 12, m[sc[10]], m[sc[11]]);
    g(s, 2, 7, 8, 13, m[sc[12]], m[sc[13]]);
    g(s, 3, 4, 9, 14, m[sc[14]], m[sc[15]]);
}

#[inline(always)]
fn compress_core(cv: &[u32; 8], m: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut s = [
        cv[0],
        cv[1],
        cv[2],
        cv[3],
        cv[4],
        cv[5],
        cv[6],
        cv[7],
        IV[0],
        IV[1],
        IV[2],
        IV[3],
        counter as u32,
        (counter >> 32) as u32,
        block_len,
        flags,
    ];
    round(&mut s, m, 0);
    round(&mut s, m, 1);
    round(&mut s, m, 2);
    round(&mut s, m, 3);
    round(&mut s, m, 4);
    round(&mut s, m, 5);
    round(&mut s, m, 6);
    s
}

#[inline(always)]
fn compress_cv(cv: &mut [u32; 8], m: &[u32; 16], counter: u64, block_len: u32, flags: u32) {
    let s = compress_core(cv, m, counter, block_len, flags);
    for i in 0..8 {
        cv[i] = s[i] ^ s[i + 8];
    }
}

fn compress_xof(cv: &[u32; 8], m: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u8; 64] {
    let mut s = compress_core(cv, m, counter, block_len, flags);
    for i in 0..8 {
        s[i] ^= s[i + 8];
        s[i + 8] ^= cv[i];
    }
    let mut out = [0u8; 64];
    for i in 0..16 {
        out[4 * i..4 * i + 4].copy_from_slice(&s[i].to_le_bytes());
    }
    out
}

#[inline(always)]
fn words_from_block(block: &[u8]) -> [u32; 16] {
    let mut m = [0u32; 16];
    for i in 0..16 {
        m[i] = u32::from_le_bytes([block[4 * i], block[4 * i + 1], block[4 * i + 2], block[4 * i + 3]]);
    }
    m
}

fn words_from_key(key: &[u8; 32]) -> [u32; 8] {
    let mut k = [0u32; 8];
    for i in 0..8 {
        k[i] = u32::from_le_bytes([key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]);
    }
    k
}

fn parent_cv(left: &[u32; 8], right: &[u32; 8], key: &[u32; 8], flags: u32) -> [u32; 8] {
    let mut m = [0u32; 16];
    m[..8].copy_from_slice(left);
    m[8..].copy_from_slice(right);
    let mut cv = *key;
    compress_cv(&mut cv, &m, 0, BLOCK_LEN as u32, flags | PARENT);
    cv
}

fn parent_output(left: &[u32; 8], right: &[u32; 8], key: &[u32; 8], flags: u32) -> Output {
    let mut m = [0u32; 16];
    m[..8].copy_from_slice(left);
    m[8..].copy_from_slice(right);
    Output {
        input_cv: *key,
        block: m,
        counter: 0,
        block_len: BLOCK_LEN as u32,
        flags: flags | PARENT,
    }
}

/// Hash one complete (non-root) 1024-byte chunk, returning its chaining value.
#[inline]
fn full_chunk_cv(chunk: &[u8], key: &[u32; 8], counter: u64, flags: u32) -> [u32; 8] {
    debug_assert_eq!(chunk.len(), CHUNK_LEN);
    let mut cv = *key;
    for b in 0..16 {
        let mut f = flags;
        if b == 0 {
            f |= CHUNK_START;
        }
        if b == 15 {
            f |= CHUNK_END;
        }
        let m = words_from_block(&chunk[b * BLOCK_LEN..(b + 1) * BLOCK_LEN]);
        compress_cv(&mut cv, &m, counter, BLOCK_LEN as u32, f);
    }
    cv
}

#[derive(Clone)]
struct Output {
    input_cv: [u32; 8],
    block: [u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    fn chaining_value(&self) -> [u32; 8] {
        let mut cv = self.input_cv;
        compress_cv(&mut cv, &self.block, self.counter, self.block_len, self.flags);
        cv
    }

    fn root_block(&self, block_counter: u64) -> [u8; 64] {
        compress_xof(&self.input_cv, &self.block, block_counter, self.block_len, self.flags | ROOT)
    }
}

#[derive(Clone)]
struct ChunkState {
    cv: [u32; 8],
    chunk_counter: u64,
    buf: [u8; BLOCK_LEN],
    buf_len: usize,
    blocks_compressed: usize,
    flags: u32,
}

impl ChunkState {
    fn new(key: &[u32; 8], chunk_counter: u64, flags: u32) -> Self {
        ChunkState {
            cv: *key,
            chunk_counter,
            buf: [0; BLOCK_LEN],
            buf_len: 0,
            blocks_compressed: 0,
            flags,
        }
    }

    fn len(&self) -> usize {
        self.blocks_compressed * BLOCK_LEN + self.buf_len
    }

    fn start_flag(&self) -> u32 {
        if self.blocks_compressed == 0 {
            CHUNK_START
        } else {
            0
        }
    }

    fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.buf_len == BLOCK_LEN {
                let m = words_from_block(&self.buf);
                let f = self.flags | self.start_flag();
                compress_cv(&mut self.cv, &m, self.chunk_counter, BLOCK_LEN as u32, f);
                self.blocks_compressed += 1;
                self.buf = [0; BLOCK_LEN];
                self.buf_len = 0;
            }
            // Fast path: compress whole blocks straight from the input when
            // the buffer is empty and more input follows them.
            if self.buf_len == 0 {
                while input.len() > BLOCK_LEN {
                    let m = words_from_block(&input[..BLOCK_LEN]);
                    let f = self.flags | self.start_flag();
                    compress_cv(&mut self.cv, &m, self.chunk_counter, BLOCK_LEN as u32, f);
                    self.blocks_compressed += 1;
                    input = &input[BLOCK_LEN..];
                }
            }
            let want = BLOCK_LEN - self.buf_len;
            let take = want.min(input.len());
            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&input[..take]);
            self.buf_len += take;
            input = &input[take..];
        }
    }

    fn output(&self) -> Output {
        Output {
            input_cv: self.cv,
            block: words_from_block(&self.buf),
            counter: self.chunk_counter,
            block_len: self.buf_len as u32,
            flags: self.flags | self.start_flag() | CHUNK_END,
        }
    }
}

fn largest_power_of_two_leq(n: u64) -> u64 {
    debug_assert!(n > 0);
    1u64 << (63 - n.leading_zeros())
}

/// Length in bytes of the left subtree for an input of `len` bytes, where
/// `len > CHUNK_LEN`.
fn left_len(len: usize) -> usize {
    let full_chunks = ((len - 1) / CHUNK_LEN) as u64;
    (largest_power_of_two_leq(full_chunks) as usize) * CHUNK_LEN
}

/// Minimum subtree size worth handing to another thread.
const MIN_PARALLEL_LEN: usize = 128 * CHUNK_LEN;

/// Compute the chaining value of a complete, non-root subtree.
fn subtree_cv(input: &[u8], key: &[u32; 8], chunk_counter: u64, flags: u32, threads: usize) -> [u32; 8] {
    if input.len() <= CHUNK_LEN {
        if input.len() == CHUNK_LEN {
            return full_chunk_cv(input, key, chunk_counter, flags);
        }
        let mut cs = ChunkState::new(key, chunk_counter, flags);
        cs.update(input);
        return cs.output().chaining_value();
    }
    let ll = left_len(input.len());
    let (left, right) = input.split_at(ll);
    let right_counter = chunk_counter + (ll / CHUNK_LEN) as u64;
    let (lcv, rcv) = if threads > 1 && input.len() >= MIN_PARALLEL_LEN {
        let lt = threads / 2;
        let rt = threads - lt;
        std::thread::scope(|s| {
            let h = std::thread::Builder::new()
                .spawn_scoped(s, move || subtree_cv(right, key, right_counter, flags, rt));
            match h {
                Ok(h) => {
                    let l = subtree_cv(left, key, chunk_counter, flags, lt.max(1));
                    let r = match h.join() {
                        Ok(r) => r,
                        Err(e) => std::panic::resume_unwind(e),
                    };
                    (l, r)
                }
                Err(_) => (
                    subtree_cv(left, key, chunk_counter, flags, 1),
                    subtree_cv(right, key, right_counter, flags, 1),
                ),
            }
        })
    } else {
        (
            subtree_cv(left, key, chunk_counter, flags, 1),
            subtree_cv(right, key, right_counter, flags, 1),
        )
    };
    parent_cv(&lcv, &rcv, key, flags)
}

#[derive(Clone)]
pub struct Hasher {
    key: [u32; 8],
    chunk_state: ChunkState,
    cv_stack: Vec<[u32; 8]>,
    flags: u32,
}

impl Hasher {
    fn new_internal(key: [u32; 8], flags: u32) -> Self {
        Hasher {
            key,
            chunk_state: ChunkState::new(&key, 0, flags),
            cv_stack: Vec::with_capacity(64),
            flags,
        }
    }

    pub fn new() -> Self {
        Self::new_internal(IV, 0)
    }

    pub fn new_keyed(key: &[u8; KEY_LEN]) -> Self {
        Self::new_internal(words_from_key(key), KEYED_HASH)
    }

    pub fn new_derive_key(context: &str) -> Self {
        let mut ctx = Self::new_internal(IV, DERIVE_KEY_CONTEXT);
        ctx.update(context.as_bytes());
        let mut ctx_key = [0u8; KEY_LEN];
        ctx.finalize_xof().fill(&mut ctx_key);
        Self::new_internal(words_from_key(&ctx_key), DERIVE_KEY_MATERIAL)
    }

    fn merge_cv_stack(&mut self, total_chunks: u64) {
        let post_merge_len = total_chunks.count_ones() as usize;
        while self.cv_stack.len() > post_merge_len {
            let right = self.cv_stack.pop().unwrap();
            let left = self.cv_stack.pop().unwrap();
            let p = parent_cv(&left, &right, &self.key, self.flags);
            self.cv_stack.push(p);
        }
    }

    fn push_cv(&mut self, cv: [u32; 8], chunk_counter: u64) {
        self.merge_cv_stack(chunk_counter);
        self.cv_stack.push(cv);
    }

    pub fn update(&mut self, input: &[u8]) -> &mut Self {
        self.update_with_threads(input, 1)
    }

    pub fn update_with_threads(&mut self, mut input: &[u8], threads: usize) -> &mut Self {
        if self.chunk_state.len() > 0 {
            let want = CHUNK_LEN - self.chunk_state.len();
            let take = want.min(input.len());
            self.chunk_state.update(&input[..take]);
            input = &input[take..];
            if input.is_empty() {
                return self;
            }
            let cv = self.chunk_state.output().chaining_value();
            let counter = self.chunk_state.chunk_counter;
            self.push_cv(cv, counter);
            self.chunk_state = ChunkState::new(&self.key, counter + 1, self.flags);
        }

        while input.len() > CHUNK_LEN {
            let counter = self.chunk_state.chunk_counter;
            let mut subtree_len = largest_power_of_two_leq(input.len() as u64) as usize;
            let count_so_far = counter * CHUNK_LEN as u64;
            while ((subtree_len - 1) as u64) & count_so_far != 0 {
                subtree_len /= 2;
            }
            let subtree_chunks = (subtree_len / CHUNK_LEN) as u64;
            if subtree_len <= CHUNK_LEN {
                let cv = full_chunk_cv(&input[..CHUNK_LEN], &self.key, counter, self.flags);
                self.push_cv(cv, counter);
            } else {
                let half = subtree_len / 2;
                let (l, r) = input[..subtree_len].split_at(half);
                let half_chunks = (half / CHUNK_LEN) as u64;
                let key = self.key;
                let flags = self.flags;
                let (lcv, rcv) = if threads > 1 && subtree_len >= MIN_PARALLEL_LEN {
                    let lt = threads / 2;
                    let rt = threads - lt;
                    std::thread::scope(|s| {
                        let h = std::thread::Builder::new().spawn_scoped(s, move || {
                            subtree_cv(r, &key, counter + half_chunks, flags, rt)
                        });
                        match h {
                            Ok(h) => {
                                let lc = subtree_cv(l, &key, counter, flags, lt.max(1));
                                let rc = match h.join() {
                                    Ok(rc) => rc,
                                    Err(e) => std::panic::resume_unwind(e),
                                };
                                (lc, rc)
                            }
                            Err(_) => (
                                subtree_cv(l, &key, counter, flags, 1),
                                subtree_cv(r, &key, counter + half_chunks, flags, 1),
                            ),
                        }
                    })
                } else {
                    (
                        subtree_cv(l, &key, counter, flags, 1),
                        subtree_cv(r, &key, counter + half_chunks, flags, 1),
                    )
                };
                self.push_cv(lcv, counter);
                self.push_cv(rcv, counter + half_chunks);
            }
            self.chunk_state.chunk_counter += subtree_chunks;
            input = &input[subtree_len..];
        }

        if !input.is_empty() {
            self.chunk_state.update(input);
            let c = self.chunk_state.chunk_counter;
            self.merge_cv_stack(c);
        }
        self
    }

    fn final_output(&self) -> Output {
        if self.cv_stack.is_empty() {
            return self.chunk_state.output();
        }
        let mut output;
        let mut remaining = self.cv_stack.len();
        if self.chunk_state.len() > 0 {
            output = self.chunk_state.output();
        } else {
            output = parent_output(
                &self.cv_stack[remaining - 2],
                &self.cv_stack[remaining - 1],
                &self.key,
                self.flags,
            );
            remaining -= 2;
        }
        while remaining > 0 {
            let cv = output.chaining_value();
            output = parent_output(&self.cv_stack[remaining - 1], &cv, &self.key, self.flags);
            remaining -= 1;
        }
        output
    }

    pub fn finalize_xof(&self) -> OutputReader {
        OutputReader {
            output: self.final_output(),
            position: 0,
        }
    }
}

/// Extendable output. Positions are tracked as a 64-bit block counter plus
/// an offset within the block, so that seeking near `u64::MAX` behaves like
/// a continuous stream.
pub struct OutputReader {
    output: Output,
    position: u128,
}

impl OutputReader {
    pub fn set_position(&mut self, pos: u64) {
        self.position = pos as u128;
    }

    pub fn fill(&mut self, mut buf: &mut [u8]) {
        while !buf.is_empty() {
            let counter = (self.position / BLOCK_LEN as u128) as u64;
            let offset = (self.position % BLOCK_LEN as u128) as usize;
            let block = self.output.root_block(counter);
            let take = (BLOCK_LEN - offset).min(buf.len());
            buf[..take].copy_from_slice(&block[offset..offset + take]);
            self.position += take as u128;
            buf = &mut buf[take..];
        }
    }
}
