//! Terminal styling helpers: ANSI style constants, color-choice detection
//! (mirroring the conventional CLICOLOR / NO_COLOR environment variables),
//! escape-sequence stripping, and terminal width detection.

use std::io::IsTerminal;

pub const ERROR: &str = "\x1b[1m\x1b[31m";
pub const HEADER: &str = "\x1b[1m\x1b[4m";
pub const LITERAL: &str = "\x1b[1m";
pub const VALID: &str = "\x1b[32m";
pub const INVALID: &str = "\x1b[33m";
pub const RESET: &str = "\x1b[0m";

#[derive(Clone, Copy)]
pub enum Stream {
    Stdout,
    Stderr,
}

fn env_non_empty(name: &str) -> bool {
    match std::env::var_os(name) {
        Some(v) => !v.is_empty(),
        None => false,
    }
}

fn clicolor() -> Option<bool> {
    let v = std::env::var_os("CLICOLOR")?;
    Some(v != "0")
}

fn term_supports_color() -> bool {
    match std::env::var_os("TERM") {
        None => false,
        Some(t) => t != "dumb",
    }
}

fn is_ci() -> bool {
    std::env::var_os("CI").is_some()
}

pub fn use_color(stream: Stream) -> bool {
    let clicolor = clicolor();
    let clicolor_enabled = clicolor.unwrap_or(false);
    let clicolor_disabled = !clicolor.unwrap_or(true);
    if env_non_empty("NO_COLOR") {
        return false;
    }
    if env_non_empty("CLICOLOR_FORCE") {
        return true;
    }
    if clicolor_disabled {
        return false;
    }
    let tty = match stream {
        Stream::Stdout => std::io::stdout().is_terminal(),
        Stream::Stderr => std::io::stderr().is_terminal(),
    };
    tty && (term_supports_color() || clicolor_enabled || is_ci())
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum St {
    Ground,
    Escape,
    EscInter,
    Csi,
    CsiIgnore,
    Osc,
    OscEsc,
    StrIgnore,
    StrIgnoreEsc,
}

/// Remove ANSI escape sequences and non-whitespace control characters,
/// keeping printable text (including any UTF-8 sequences) intact.
pub fn strip(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut st = St::Ground;
    for c in input.chars() {
        let b = c as u32;
        match st {
            St::Ground => {
                if c == '\x1b' {
                    st = St::Escape;
                } else if b < 0x20 {
                    if c == '\t' || c == '\n' || c == '\r' || c == '\x0c' {
                        out.push(c);
                    }
                } else if b == 0x7f {
                    // DEL is dropped
                } else {
                    out.push(c);
                }
            }
            St::Escape => {
                st = match c {
                    '[' => St::Csi,
                    ']' => St::Osc,
                    'P' | 'X' | '^' | '_' => St::StrIgnore,
                    '\x20'..='\x2f' => St::EscInter,
                    '\x1b' => St::Escape,
                    _ if b < 0x20 => St::Escape,
                    _ => St::Ground,
                };
            }
            St::EscInter => {
                if ('\x30'..='\x7e').contains(&c) {
                    st = St::Ground;
                } else if c == '\x1b' {
                    st = St::Escape;
                }
            }
            St::Csi | St::CsiIgnore => {
                if c == '\x1b' {
                    st = St::Escape;
                } else if ('\x40'..='\x7e').contains(&c) {
                    st = St::Ground;
                } else if b < 0x20 || ('\x20'..='\x3f').contains(&c) {
                    // parameters, intermediates, and embedded controls
                } else {
                    st = St::CsiIgnore;
                }
            }
            St::Osc => {
                if c == '\x07' {
                    st = St::Ground;
                } else if c == '\x1b' {
                    st = St::OscEsc;
                }
            }
            St::OscEsc => {
                st = if c == '\\' { St::Ground } else if c == '\x1b' { St::OscEsc } else { St::Osc };
            }
            St::StrIgnore => {
                if c == '\x1b' {
                    st = St::StrIgnoreEsc;
                }
            }
            St::StrIgnoreEsc => {
                st = if c == '\\' { St::Ground } else if c == '\x1b' { St::StrIgnoreEsc } else { St::StrIgnore };
            }
        }
    }
    out
}

pub fn render(s: &str, color: bool) -> String {
    if color {
        s.to_string()
    } else {
        strip(s)
    }
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn size_of_fd(fd: i32) -> Option<usize> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize {
            ws_row: 0,
            ws_col: 0,
            ws_xpixel: 0,
            ws_ypixel: 0,
        };
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

/// The width used for wrapping help output.
pub fn term_width() -> usize {
    let current = size_of_fd(1)
        .or_else(|| size_of_fd(2))
        .or_else(|| size_of_fd(0))
        .or_else(|| {
            std::env::var_os("COLUMNS")
                .and_then(|v| v.to_str().map(|s| s.to_string()))
                .and_then(|s| s.parse::<usize>().ok())
        })
        .unwrap_or(100);
    current.min(100)
}
