//! Command line parsing for b3sum. This reproduces the argument grammar,
//! validation rules, error messages, usage strings, and help layout of the
//! tool's command line interface.

use crate::style::{self, Stream, ERROR, HEADER, INVALID, LITERAL, RESET, VALID};
use std::ffi::{OsStr, OsString};
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::Path;

pub const NAME: &str = "b3sum";
pub const VERSION: &str = "1.8.4";

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Id {
    File,
    Keyed,
    DeriveKey,
    Length,
    Seek,
    NumThreads,
    NoMmap,
    NoNames,
    Raw,
    Tag,
