        default: None,
        conflicts: &[],
        requires: &[],
    },
];

fn def(id: Id) -> &'static ArgDef {
    ARGS.iter().find(|a| a.id == id).expect("unknown arg id")
}

fn takes_value(d: &ArgDef) -> bool {
    matches!(d.kind, Kind::Opt | Kind::Pos)
}

fn in_group(id: Id) -> bool {
    !matches!(id, Id::Help | Id::Version | Id::Group)
}

/// Plain rendering of an argument, e.g. `--length <LEN>` or `[FILE]...`.
fn arg_plain(id: Id) -> String {
    let d = def(id);
    match d.kind {
        Kind::Pos => format!("[{}]...", d.value_name),
        Kind::Opt => format!("--{} <{}>", d.long.unwrap(), d.value_name),
        _ => format!("--{}", d.long.unwrap()),
    }
}

/// Styled rendering of an argument as it appears in a usage string, with
/// positionals rendered as required (`<FILE>...`).
fn arg_usage_styled(id: Id) -> String {
    let d = def(id);
    match d.kind {
        Kind::Pos => format!("<{}>...", d.value_name),
        Kind::Opt => format!("{LITERAL}--{}{RESET} <{}>", d.long.unwrap(), d.value_name),
        _ => format!("{LITERAL}--{}{RESET}", d.long.unwrap()),
    }
}

fn format_group() -> String {
    let parts: Vec<String> = ARGS
        .iter()
        .filter(|a| in_group(a.id))
        .map(|a| if a.kind == Kind::Pos { a.value_name.to_string() } else { arg_plain(a.id) })
        .collect();
    format!("<{}>", parts.join("|"))
}

fn conflicts(a: Id, b: Id) -> bool {
    if a == Id::Group || b == Id::Group {
        return false;
    }
    def(a).conflicts.contains(&b)
}

fn mutually_conflict(a: Id, b: Id) -> bool {
    conflicts(a, b) || conflicts(b, a)
}

fn unroll_requires(id: Id) -> Vec<Id> {
    let mut processed: Vec<Id> = Vec::new();
    let mut stack = vec![id];
    let mut out = Vec::new();
    while let Some(a) = stack.pop() {
        if processed.contains(&a) {
            continue;
        }
        processed.push(a);
        if a == Id::Group {
            continue;
        }
        for &r in def(a).requires {
            if !def(r).requires.is_empty() {
                stack.push(r);
            }
            out.push(r);
        }
    }
    out
}

/// Build a usage string (without the "Usage:" title).
fn usage_body(bin: &str, incls: &[Id], required: &[Id]) -> String {
    let mut s = String::new();
    if !bin.is_empty() {
        s.push_str(&format!("{LITERAL}{bin}{RESET} "));
    }
    if incls.is_empty() {
        s.push_str("[OPTIONS] ");
    }
    let mut unrolled: Vec<Id> = Vec::new();
    for &a in required {
        unrolled.extend(unroll_requires(a));
        unrolled.push(a);
    }
    let all: Vec<Id> = unrolled.iter().chain(incls.iter()).copied().collect();
    let has_group = all.contains(&Id::Group);
    let mut opts: Vec<Id> = Vec::new();
    let mut pos: Option<String> = None;
    for &id in &all {
        if id == Id::Group {
            continue;
        }
        if has_group && in_group(id) {
            continue;
        }
        if def(id).kind == Kind::Pos {
            pos = Some(arg_usage_styled(id));
        } else if !opts.contains(&id) {
            opts.push(id);
        }
    }
    if !has_group && pos.is_none() {
        pos = Some(arg_plain(Id::File));
    }
    for id in opts {
        s.push_str(&arg_usage_styled(id));
        s.push(' ');
    }
    if has_group {
        s.push_str(&format_group());
        s.push(' ');
    }
    if let Some(p) = pos {
        s.push_str(&p);
        s.push(' ');
    }
    s.trim_end().to_string()
}

fn usage(bin: &str, incls: &[Id], required: &[Id]) -> String {
    format!("{HEADER}Usage:{RESET} {}", usage_body(bin, incls, required))
}

pub enum CliError {
    Help(bool),
    Version,
    Error(String),
}

fn finish_error(mut body: String, usage: Option<String>) -> CliError {
    if let Some(u) = usage {
        body.push_str("\n\n");
        body.push_str(&u);
    }
    body.push_str(&format!("\n\nFor more information, try '{LITERAL}--help{RESET}'.\n"));
    CliError::Error(format!("{ERROR}error:{RESET} {body}"))
}

impl CliError {
    pub fn exit(self, bin: &str) -> ! {
        use std::io::Write;
        match self {
            CliError::Help(use_long) => {
                let text = render_help(bin, use_long, style::term_width());
                let color = style::use_color(Stream::Stdout);
                let out = style::render(&text, color);
                let stdout = std::io::stdout();
                let mut lock = stdout.lock();
                let _ = lock.write_all(out.as_bytes());
                let _ = lock.flush();
                drop(lock);
                std::process::exit(0);
            }
            CliError::Version => {
                let stdout = std::io::stdout();
                let mut lock = stdout.lock();
                let _ = lock.write_all(format!("{NAME} {VERSION}\n").as_bytes());
                let _ = lock.flush();
                drop(lock);
                std::process::exit(0);
            }
            CliError::Error(text) => {
                let color = style::use_color(Stream::Stderr);
                let out = style::render(&text, color);
                let stderr = std::io::stderr();
                let mut lock = stderr.lock();
                let _ = lock.write_all(out.as_bytes());
                let _ = lock.flush();
                drop(lock);
                std::process::exit(2);
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ident {
    Short,
    Long,
    Index,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum State {
    ValuesDone,
    Opt(Id),
    Pos,
}

#[derive(Default, Debug)]
pub struct Parsed {
    pub files: Vec<OsString>,
    pub keyed: bool,
    pub derive_key: Option<String>,
    pub length: u64,
    pub seek: u64,
    pub num_threads: Option<usize>,
    pub no_mmap: bool,
    pub no_names: bool,
    pub raw: bool,
    pub tag: bool,
    pub check: bool,
    pub quiet: bool,
}

struct Parser {
    bin: String,
    order: Vec<Id>,
    pending: Option<(Id, Ident, Vec<OsString>)>,
    out: Parsed,
    length_set: bool,
    seek_set: bool,
}

fn lossy(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

fn invalid_utf8_error(bin: &str) -> CliError {
    finish_error(
        "invalid UTF-8 was detected in one or more arguments".to_string(),
        Some(usage(bin, &[], &[])),
    )
}

fn empty_value_error(arg: &str) -> CliError {
    finish_error(format!("a value is required for '{INVALID}{arg}{RESET}' but none was supplied"), None)
}

fn value_validation_error(arg: &str, val: &str, err: &str) -> CliError {
    finish_error(format!("invalid value '{INVALID}{val}{RESET}' for '{LITERAL}{arg}{RESET}': {err}"), None)
}

/// Jaro similarity over Unicode scalar values.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && *ac == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut bi = 0usize;
        for (i, ac) in a.iter().enumerate() {
            if a_flags[i] {
                while bi < b_len {
                    let j = bi;
                    bi += 1;
                    if !b_flags[j] {
                        continue;
                    }
                    if *ac != b[j] {
                        transpositions += 1;
                    }
                    break;
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

impl Parser {
    fn present(&self, id: Id) -> bool {
        self.order.contains(&id)
    }

    fn start_arg(&mut self, id: Id) {
        if !self.order.contains(&id) {
            self.order.push(id);
        }
        if in_group(id) && !self.order.contains(&Id::Group) {
            self.order.push(Id::Group);
        }
    }

    fn resolve_pending(&mut self) -> Result<(), CliError> {
        if let Some((id, ident, vals)) = self.pending.take() {
            self.react(id, ident, vals)?;
        }
        Ok(())
    }

    fn dup_error(&self, id: Id) -> CliError {
        finish_error(
            format!("the argument '{INVALID}{}{RESET}' cannot be used multiple times", arg_plain(id)),
            Some(usage(&self.bin, &[], &[])),
        )
    }

    fn parse_u64(&self, id: Id, raw: &OsStr) -> Result<u64, CliError> {
        let s = raw.to_str().ok_or_else(|| invalid_utf8_error(&self.bin))?;
        s.parse::<u64>()
            .map_err(|e| value_validation_error(&arg_plain(id), s, &e.to_string()))
    }

    fn react(&mut self, id: Id, ident: Ident, vals: Vec<OsString>) -> Result<(), CliError> {
        self.resolve_pending()?;
        let d = def(id);
        if takes_value(d) && vals.is_empty() {
            return Err(empty_value_error(&arg_plain(id)));
        }
        match d.kind {
            Kind::Help => Err(CliError::Help(ident != Ident::Short)),
            Kind::Version => Err(CliError::Version),
            Kind::Flag => {
                if self.present(id) {
                    return Err(self.dup_error(id));
                }
                self.start_arg(id);
                match id {
                    Id::Keyed => self.out.keyed = true,
                    Id::NoMmap => self.out.no_mmap = true,
                    Id::NoNames => self.out.no_names = true,
                    Id::Raw => self.out.raw = true,
                    Id::Tag => self.out.tag = true,
                    Id::Check => self.out.check = true,
                    Id::Quiet => self.out.quiet = true,
                    _ => {}
                }
                Ok(())
            }
            Kind::Opt => {
                if self.present(id) {
                    return Err(self.dup_error(id));
                }
                self.start_arg(id);
                let raw = &vals[0];
                match id {
                    Id::DeriveKey => {
                        let s = raw.to_str().ok_or_else(|| invalid_utf8_error(&self.bin))?;
                        self.out.derive_key = Some(s.to_string());
                    }
                    Id::Length => {
                        self.out.length = self.parse_u64(id, raw)?;
                        self.length_set = true;
                    }
                    Id::Seek => {
                        self.out.seek = self.parse_u64(id, raw)?;
                        self.seek_set = true;
                    }
                    Id::NumThreads => {
                        let s = raw.to_str().ok_or_else(|| invalid_utf8_error(&self.bin))?;
                        let n = s
                            .parse::<usize>()
                            .map_err(|e| value_validation_error(&arg_plain(id), s, &e.to_string()))?;
                        self.out.num_threads = Some(n);
                    }
                    _ => {}
                }
                Ok(())
            }
            Kind::Pos => {
                self.start_arg(id);
                for v in vals {
                    if v.is_empty() {
                        return Err(empty_value_error(&arg_plain(id)));
                    }
                    self.out.files.push(v);
                }
                Ok(())
            }
        }
    }

    fn explicit_args(&self) -> Vec<Id> {
        self.order.iter().copied().filter(|&i| i != Id::Group).collect()
    }

    fn did_you_mean_error(&mut self, arg: &str) -> CliError {
        let mut best: Option<(f64, Id)> = None;
        for a in ARGS.iter() {
            if let Some(l) = a.long {
                let conf = jaro(arg, l);
                if conf > 0.7 {
                    match best {
                        Some((b, _)) if conf < b => {}
                        _ => best = Some((conf, a.id)),
                    }
                }
            }
        }
        if let Some((_, id)) = best {
            self.start_arg(id);
        }
        let used = self.explicit_args();
        let mut body = format!("unexpected argument '{INVALID}--{arg}{RESET}' found");
        if let Some((_, id)) = best {
            body.push_str(&format!(
                "\n\n  {VALID}tip:{RESET} a similar argument exists: '{VALID}--{}{RESET}'",
                def(id).long.unwrap()
            ));
        } else {
            body.push_str(&format!(
                "\n\n  {VALID}tip:{RESET} to pass '{INVALID}--{arg}{RESET}' as a value, use '{VALID}-- --{arg}{RESET}'"
            ));
        }
        finish_error(body, Some(usage(&self.bin, &used, &[])))
    }

    fn unknown_short_error(&self, arg: &str) -> CliError {
        let body = format!(
            "unexpected argument '{INVALID}{arg}{RESET}' found\n\n  {VALID}tip:{RESET} to pass '{INVALID}{arg}{RESET}' as a value, use '{VALID}-- {arg}{RESET}'"
        );
        finish_error(body, Some(usage(&self.bin, &[], &[])))
    }

    /// Parse a cluster of short flags (the bytes after the leading '-').
    fn parse_short(&mut self, rest: &[u8]) -> Result<State, CliError> {
        let (prefix, suffix): (&str, Option<&[u8]>) = match std::str::from_utf8(rest) {
            Ok(s) => (s, None),
            Err(e) => {
                let v = e.valid_up_to();
                (std::str::from_utf8(&rest[..v]).unwrap(), Some(&rest[v..]))
            }
        };
        let mut chars = prefix.char_indices().peekable();
        loop {
            let (idx, c) = match chars.next() {
                Some(x) => x,
                None => {
                    if let Some(sfx) = suffix {
                        let _ = self.resolve_pending();
                        return Err(self.unknown_short_error(&format!("-{}", lossy(sfx))));
                    }
                    break;
                }
            };
            let found = ARGS.iter().find(|a| a.short == Some(c));
            let d = match found {
                Some(d) => d,
                None => {
                    let _ = self.resolve_pending();
                    return Err(self.unknown_short_error(&format!("-{c}")));
                }
            };
            if !takes_value(d) {
                self.react(d.id, Ident::Short, Vec::new())?;
                continue;
            }
            let after = idx + c.len_utf8();
            let mut val: Vec<u8> = prefix.as_bytes()[after..].to_vec();
            if let Some(sfx) = suffix {
                val.extend_from_slice(sfx);
            }
            if !val.is_empty() {
                if val[0] == b'=' {
                    val.remove(0);
                }
                self.react(d.id, Ident::Short, vec![OsString::from_vec(val)])?;
                return Ok(State::ValuesDone);
            }
            self.resolve_pending()?;
            self.pending = Some((d.id, Ident::Short, Vec::new()));
            return Ok(State::Opt(d.id));
        }
        Ok(State::ValuesDone)
    }

    fn parse_long(&mut self, raw: &[u8]) -> Result<State, CliError> {
        let (flag, value): (&[u8], Option<&[u8]>) = match raw.iter().position(|&b| b == b'=') {
            Some(i) => (&raw[..i], Some(&raw[i + 1..])),
            None => (raw, None),
        };
        let name = match std::str::from_utf8(flag) {
            Ok(s) => s.to_string(),
            Err(_) => {
                let n = lossy(flag);
                let _ = self.resolve_pending();
                return Err(self.did_you_mean_error(&n));
            }
        };
        let found = if name.is_empty() { None } else { ARGS.iter().find(|a| a.long == Some(name.as_str())) };
        let d = match found {
            Some(d) => d,
            None => {
                let _ = self.resolve_pending();
                return Err(self.did_you_mean_error(&name));
            }
        };
        if takes_value(d) {
            if let Some(v) = value {
                self.react(d.id, Ident::Long, vec![OsString::from_vec(v.to_vec())])?;
                return Ok(State::ValuesDone);
            }
            self.resolve_pending()?;
            self.pending = Some((d.id, Ident::Long, Vec::new()));
            return Ok(State::Opt(d.id));
        }
        if let Some(v) = value {
            let mut used: Vec<Id> = self.order.clone();
            used.push(d.id);
            let body = format!(
                "unexpected value '{INVALID}{}{RESET}' for '{LITERAL}{}{RESET}' found; no more were expected",
                lossy(v),
                arg_plain(d.id)
            );
            let _ = self.resolve_pending();
            return Err(finish_error(body, Some(usage(&self.bin, &used, &[]))));
        }
        self.react(d.id, Ident::Long, Vec::new())?;
        Ok(State::ValuesDone)
    }

    fn run(&mut self, args: &[OsString]) -> Result<(), CliError> {
        let mut trailing = false;
        let mut state = State::ValuesDone;
        for a in args {
            let bytes = a.as_bytes();
            if !trailing {
                if bytes == b"--" {
                    trailing = true;
                    continue;
                } else if bytes.starts_with(b"--") {
                    state = self.parse_long(&bytes[2..])?;
                    continue;
                } else if bytes.len() > 1 && bytes[0] == b'-' {
                    state = self.parse_short(&bytes[1..])?;
                    continue;
                }
                if let State::Opt(id) = state {
                    match &mut self.pending {
                        Some((pid, _, vals)) if *pid == id => vals.push(a.clone()),
                        _ => self.pending = Some((id, Ident::Long, vec![a.clone()])),
                    }
                    state = State::ValuesDone;
                    continue;
                }
            }
            // Positional value.
            let pending_is_file = matches!(&self.pending, Some((Id::File, _, _)));
            if !pending_is_file {
                self.resolve_pending()?;
            }
            match &mut self.pending {
                Some((Id::File, _, vals)) => vals.push(a.clone()),
                _ => self.pending = Some((Id::File, Ident::Index, vec![a.clone()])),
            }
            state = State::Pos;
        }
        let _ = state;
        self.resolve_pending()?;
        self.validate()
    }

    fn validate(&mut self) -> Result<(), CliError> {
        let present = self.explicit_args();
        // Conflicts.
        for &id in &present {
            let mut confs: Vec<Id> = Vec::new();
            for &other in &present {
                if other == id {
                    continue;
                }
                if conflicts(id, other) {
                    confs.push(other);
                }
                if conflicts(other, id) {
                    confs.push(other);
                }
            }
            if confs.is_empty() {
                continue;
            }
            let mut seen: Vec<Id> = Vec::new();
            for &c in &confs {
                if !seen.contains(&c) {
                    seen.push(c);
                }
            }
            let mut body = format!("the argument '{INVALID}{}{RESET}' cannot be used with", arg_plain(id));
            if seen.len() == 1 {
                body.push_str(&format!(" '{INVALID}{}{RESET}'", arg_plain(seen[0])));
            } else {
                body.push(':');
                for &c in &seen {
                    body.push_str(&format!("\n  {INVALID}{}{RESET}", arg_plain(c)));
                }
            }
            let used_filtered: Vec<Id> = present.iter().copied().filter(|x| !confs.contains(x)).collect();
            let mut req: Vec<Id> = Vec::new();
            for &u in &used_filtered {
                for &r in def(u).requires {
                    if !used_filtered.contains(&r) && !confs.contains(&r) {
                        req.push(r);
                    }
                }
            }
            req.extend(used_filtered.iter().copied());
            return Err(finish_error(body, Some(usage(&self.bin, &req, &[]))));
        }
        // Requirements.
        let mut required: Vec<Id> = Vec::new();
        for &id in &present {
            for r in unroll_requires(id) {
                if !required.contains(&r) {
                    required.push(r);
                }
            }
        }
        let mut missing: Vec<Id> = Vec::new();
        for &r in &required {
            if present.contains(&r) {
                continue;
            }
            let ok = present.iter().any(|&p| p != r && mutually_conflict(r, p));
            if !ok {
                missing.push(r);
            }
        }
        if !missing.is_empty() {
            let mut unrolled: Vec<Id> = Vec::new();
            for &a in &required {
                unrolled.extend(unroll_requires(a));
                unrolled.push(a);
            }
            let mut opts: Vec<Id> = Vec::new();
            let mut pos: Option<Id> = None;
            for &r in unrolled.iter().chain(missing.iter()) {
                if present.contains(&r) {
                    continue;
                }
                if def(r).kind == Kind::Pos {
                    pos = Some(r);
                } else if !opts.contains(&r) {
                    opts.push(r);
                }
            }
            let mut body = String::from("the following required arguments were not provided:");
            for &o in &opts {
                body.push_str(&format!("\n  {VALID}{}{RESET}", arg_plain(o)));
            }
            if let Some(p) = pos {
                body.push_str(&format!("\n  {VALID}<{}>...{RESET}", def(p).value_name));
            }
            let mut used = present.clone();
            used.extend(missing.iter().copied());
            return Err(finish_error(body, Some(usage(&self.bin, &used, &required))));
        }
        Ok(())
    }
}

pub fn bin_name(args: &[OsString]) -> String {
    if let Some(a0) = args.first() {
        if let Some(f) = Path::new(a0).file_name() {
            if let Some(s) = f.to_str() {
                return s.to_string();
            }
        }
    }
    NAME.to_string()
}

pub fn parse(args: &[OsString]) -> Result<Parsed, (CliError, String)> {
    let bin = bin_name(args);
    let mut p = Parser {
        bin: bin.clone(),
        order: Vec::new(),
        pending: None,
        out: Parsed::default(),
        length_set: false,
        seek_set: false,
    };
    let rest = if args.is_empty() { &args[..] } else { &args[1..] };
    match p.run(rest) {
        Ok(()) => {
            if !p.length_set {
                p.out.length = 32;
            }
            if !p.seek_set {
                p.out.seek = 0;
            }
            Ok(p.out)
        }
        Err(e) => Err((e, bin)),
    }
}

// ---------------------------------------------------------------------------
// Help rendering
// ---------------------------------------------------------------------------

/// Split a line into words, each word carrying its trailing spaces.
fn find_words(line: &str) -> Vec<&str> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_ws = false;
    for (idx, ch) in line.char_indices() {
        if in_ws && ch != ' ' {
            words.push(&line[start..idx]);
            start = idx;
        }
        in_ws = ch == ' ';
    }
    if start < line.len() {
        words.push(&line[start..]);
    }
    words
}

fn display_width(s: &str) -> usize {
    s.chars().count()
}

fn wrap_text(content: &str, hard_width: usize) -> String {
    let mut out = String::new();
    let mut line_width;
    for line in content.split_inclusive('\n') {
        line_width = 0usize;
        let mut words: Vec<&str> = find_words(line);
        let carryover: &str = match words.first() {
            Some(w) if w.trim().is_empty() => w,
            _ => "",
        };
        let mut i = 0;
        while i < words.len() {
            let word = words[i];
            let trimmed = word.trim_end();
            let word_width = display_width(trimmed);
            let trimmed_delta = word.len() - trimmed.len();
            if i != 0 && hard_width < line_width + word_width {
                let last = i - 1;
                words[last] = words[last].trim_end();
                line_width = 0;
                words.insert(i, "\n");
                i += 1;
                words.insert(i, carryover);
                line_width += carryover.len();
                i += 1;
            }
            line_width += word_width + trimmed_delta;
            i += 1;
        }
        for w in words {
            out.push_str(w);
        }
    }
    out.trim_end().to_string()
}

fn spec_vals(d: &ArgDef) -> String {
    match d.default {
        Some(v) => format!("[default: {v}]"),
        None => String::new(),
    }
}

fn arg_next_line_help(d: &ArgDef, longest: usize, term_w: usize, use_long: bool) -> bool {
    if use_long {
        return true;
    }
    let h_w = display_width(d.help) + display_width(&spec_vals(d));
    let taken = if d.kind == Kind::Pos { longest + 4 } else { longest + 8 };
    term_w >= taken && (taken as f32 / term_w as f32) > 0.40 && h_w > (term_w - taken)
}

fn write_section(ids: &[Id], use_long: bool, term_w: usize) -> String {
    let mut longest = 2usize;
    for &id in ids {
        longest = longest.max(display_width(&arg_plain(id)));
    }
    let next_line = ids.iter().any(|&id| arg_next_line_help(def(id), longest, term_w, use_long));
    let mut out = String::new();
    for (i, &id) in ids.iter().enumerate() {
        if i != 0 {
            out.push('\n');
            if next_line && use_long {
                out.push('\n');
            }
        }
        let d = def(id);
        let mut written = 2usize;
        out.push_str("  ");
        if let Some(s) = d.short {
            out.push_str(&format!("{LITERAL}-{s}{RESET}"));
            written += 2;
        } else if d.long.is_some() {
            out.push_str("    ");
            written += 4;
        }
        if let Some(l) = d.long {
            if d.short.is_some() {
                out.push_str(", ");
                written += 2;
            }
            out.push_str(&format!("{LITERAL}--{l}{RESET}"));
            written += 2 + l.len();
        }
        match d.kind {
            Kind::Opt => {
                let s = format!(" <{}>", d.value_name);
                written += s.len();
                out.push_str(&s);
            }
            Kind::Pos => {
                let s = arg_plain(id);
                written += s.len();
                out.push_str(&s);
            }
            _ => {}
        }
        let spaces = if next_line {
            10
        } else if d.kind == Kind::Pos {
            longest + 4
        } else {
            longest + 8
        };
        if next_line {
            out.push('\n');
            out.push_str(&" ".repeat(10));
        } else {
            out.push_str(&" ".repeat(spaces.saturating_sub(written)));
        }
        let about = if use_long { d.long_help.unwrap_or(d.help) } else { d.help };
        let mut text = about.to_string();
        let sv = spec_vals(d);
        if !sv.is_empty() {
            if !text.is_empty() {
                text.push_str(if use_long { "\n\n" } else { " " });
            }
            text.push_str(&sv);
        }
        let avail = term_w.saturating_sub(spaces);
        let wrapped = wrap_text(&text, avail);
        let indent = format!("\n{}", " ".repeat(spaces));
        out.push_str(&wrapped.replace('\n', &indent));
    }
    out
}

pub fn render_help(bin: &str, use_long: bool, term_w: usize) -> String {
    let mut out = String::new();
    out.push_str(&usage(bin, &[], &[]));
    out.push_str("\n\n");
    out.push_str(&format!("{HEADER}Arguments:{RESET}\n"));
    out.push_str(&write_section(&[Id::File], use_long, term_w));
    out.push_str("\n\n");
    out.push_str(&format!("{HEADER}Options:{RESET}\n"));
    let opts = [
        Id::Keyed,
        Id::DeriveKey,
        Id::Length,
        Id::Seek,
        Id::NumThreads,
        Id::NoMmap,
        Id::NoNames,
        Id::Raw,
        Id::Tag,
        Id::Check,
        Id::Quiet,
        Id::Help,
        Id::Version,
    ];
    out.push_str(&write_section(&opts, use_long, term_w));
    let trimmed = out.trim_end().to_string();
    trimmed + "\n"
}
