    let mut block = [0u8; 4096];
    let mut s = String::with_capacity(8192);
    while remaining > 0 {
        let take = remaining.min(block.len() as u64) as usize;
        output.fill(&mut block[..take]);
        s.clear();
        hex_encode(&block[..take], &mut s);
        print!("{}", s);
        remaining -= take as u64;
    }
