        lock.write_all(&buf[..take])?;
        remaining -= take as u64;
    }
    Ok(())
}

struct FilepathString {
    filepath_string: String,
    is_escaped: bool,
}

fn filepath_to_string(path: &Path) -> FilepathString {
    let mut s = path.to_string_lossy().into_owned();
    let mut is_escaped = false;
    if s.contains(['\\', '\n', '\r']) {
        s = s.replace('\\', "\\\\").replace('\n', "\\n").replace('\r', "\\r");
        is_escaped = true;
    }
    FilepathString { filepath_string: s, is_escaped }
}

fn hash_one_input(path: &Path, args: &Args) -> Result<()> {
    let output = hash_path(args, path)?;
    if args.inner.raw {
        return write_raw_output(output, args.inner.length);
    }
    if args.inner.no_names {
        write_hex_output(output, args.inner.length);
        println!();
        return Ok(());
    }
    let FilepathString { filepath_string, is_escaped } = filepath_to_string(path);
    if is_escaped {
        print!("\\");
    }
    if args.inner.tag {
        print!("BLAKE3 ({}) = ", filepath_string);
        write_hex_output(output, args.inner.length);
        println!();
        return Ok(());
    }
    write_hex_output(output, args.inner.length);
    println!("  {}", filepath_string);
    Ok(())
}

struct ParsedCheckLine {
    file_string: String,
    is_escaped: bool,
    file_path: PathBuf,
    expected_hash: [u8; OUT_LEN],
}

fn hex_half_byte(c: u8) -> Result<u8> {
    match c {
        b'0'..=b'9' => Ok(c - b'0'),
        b'a'..=b'f' => Ok(c - b'a' + 10),
        _ => err("Invalid hex"),
    }
}

fn unescape(path: &str) -> Result<String> {
    let mut out = String::with_capacity(path.len());
    let mut chars = path.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('\\') => out.push('\\'),
                _ => return err("Invalid backslash escape"),
            }
        } else {
            out.push(c);
        }
    }
    Ok(out)
}

fn check_for_invalid_characters(path: &str) -> Result<()> {
    if path.contains('\0') {
        return err("Null character in path");
    }
    if path.contains('\u{FFFD}') {
        return err("Unicode replacement character in path");
    }
    Ok(())
}

fn parse_check_line(line: &str) -> Result<ParsedCheckLine> {
    let mut line = line.trim_end_matches(['\r', '\n']);
    if line.is_empty() {
        return err("Empty line");
    }
    let mut is_escaped = false;
    if let Some(rest) = line.strip_prefix('\\') {
        is_escaped = true;
        line = rest;
    }
    let (hash_hex, file_string) = if let Some((h, f)) = line.split_once("  ") {
        (h, f)
    } else if let Some(rest) = line.strip_prefix("BLAKE3 (") {
        match rest.rsplit_once(") = ") {
            Some((f, h)) => (h, f),
            None => return err("Invalid check line format"),
        }
    } else {
        return err("Invalid check line format");
    };
    if hash_hex.len() != 2 * OUT_LEN {
        return err("Invalid hash length");
    }
    let hb = hash_hex.as_bytes();
    let mut expected_hash = [0u8; OUT_LEN];
    for i in 0..OUT_LEN {
        expected_hash[i] = 16 * hex_half_byte(hb[2 * i])? + hex_half_byte(hb[2 * i + 1])?;
    }
    if file_string.is_empty() {
        return err("empty file path");
    }
    let path_string = if is_escaped { unescape(file_string)? } else { file_string.to_string() };
    check_for_invalid_characters(&path_string)?;
    Ok(ParsedCheckLine {
        file_string: file_string.to_string(),
        is_escaped,
        file_path: PathBuf::from(path_string),
        expected_hash,
    })
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0 && a.len() == b.len()
}

fn check_one_line(line: &str, args: &Args) -> bool {
    let parsed = match parse_check_line(line) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}: {}", NAME, e);
            return false;
        }
    };
    let ParsedCheckLine { file_string, is_escaped, file_path, expected_hash } = parsed;
    let file_string = if is_escaped { format!("\\{}", file_string) } else { file_string };
    let found = match hash_path(args, &file_path) {
        Ok(mut output) => {
            let mut bytes = [0u8; OUT_LEN];
            output.fill(&mut bytes);
            bytes
        }
        Err(e) => {
            println!("{}: FAILED ({})", file_string, e);
            return false;
        }
    };
    if constant_time_eq(&expected_hash, &found) {
        if !args.inner.quiet {
            println!("{}: OK", file_string);
        }
        true
    } else {
        println!("{}: FAILED", file_string);
        false
    }
}

fn check_lines(mut reader: impl BufRead, args: &Args, files_failed: &mut u64) -> Result<()> {
    let mut line = String::new();
    loop {
        line.clear();
        let n = reader.read_line(&mut line)?;
        if n == 0 {
            return Ok(());
        }
        if !check_one_line(&line, args) {
            *files_failed = files_failed.checked_add(1).unwrap();
        }
    }
}

fn check_one_checkfile(path: &Path, args: &Args, files_failed: &mut u64) -> Result<()> {
    if path == Path::new("-") {
        let stdin = io::stdin();
        let lock = stdin.lock();
        check_lines(io::BufReader::new(lock), args, files_failed)
    } else {
        let file = File::open(path)?;
        check_lines(io::BufReader::new(file), args, files_failed)
    }
}

fn run(args: Args) -> Result<i32> {
    let mut files_failed = 0u64;
    for path in &args.file_args {
        if args.inner.check {
            check_one_checkfile(path, &args, &mut files_failed)?;
        } else if let Err(e) = hash_one_input(path, &args) {
            files_failed += 1;
            eprintln!("{}: {}: {}", NAME, path.to_string_lossy(), e);
        }
    }
    if args.inner.check && files_failed > 0 {
        eprintln!(
            "{}: WARNING: {} computed checksum{} did NOT match",
            NAME,
            files_failed,
            if files_failed == 1 { "" } else { "s" },
        );
    }
    Ok(if files_failed > 0 { 1 } else { 0 })
}

fn fail(e: Error) -> ! {
    eprintln!("Error: {}", e);
    std::process::exit(1);
}

fn main() {
    let raw_args: Vec<OsString> = std::env::args_os().collect();
    let inner = match cli::parse(&raw_args) {
        Ok(p) => p,
        Err((e, bin)) => e.exit(&bin),
    };
    let file_args: Vec<PathBuf> = if !inner.files.is_empty() {
        inner.files.iter().map(PathBuf::from).collect()
    } else {
        vec![PathBuf::from("-")]
    };
    if inner.raw && file_args.len() > 1 {
        fail(Error("Only one filename can be provided when using --raw".to_string()));
    }
    let base_hasher = if inner.keyed {
        match read_key_from_stdin() {
            Ok(key) => Hasher::new_keyed(&key),
            Err(e) => fail(e),
        }
    } else if let Some(ref context) = inner.derive_key {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };
    let threads = default_threads(inner.num_threads);
    let args = Args { inner, file_args, base_hasher, threads };

    let worker = std::thread::Builder::new().spawn(move || match run(args) {
        Ok(code) => std::process::exit(code),
        Err(e) => fail(e),
    });
    match worker {
        Ok(handle) => match handle.join() {
            Ok(()) => {}
            Err(payload) => std::panic::resume_unwind(payload),
        },
        Err(e) => {
            eprintln!("Error: {}\n\nCaused by:\n    {}", e, e);
            std::process::exit(1);
        }
    }
}
