                5, 4, 7, 6, 1, 0, 3, 2,
            ),
        )
    }

    #[inline(always)]
    unsafe fn rot12(x: __m256i) -> __m256i {
        _mm256_or_si256(_mm256_srli_epi32(x, 12), _mm256_slli_epi32(x, 20))
    }

    #[inline(always)]
    unsafe fn rot8(x: __m256i) -> __m256i {
