    /// Hash eight inputs of `blocks` 64-byte blocks each. Input `i` starts at
    /// `base + i * stride`. When `increment_counter` is set, lane `i` uses
    /// counter `counter + i`; otherwise every lane uses `counter`.
    /// Outputs the eight resulting chaining values.
    #[target_feature(enable = "avx2")]
    pub unsafe fn hash8(
        base: *const u8,
        stride: usize,
        blocks: usize,
        key: &[u32; 8],
        counter: u64,
        increment_counter: bool,
        flags: u32,
        flags_start: u32,
        flags_end: u32,
        out: &mut [[u32; 8]; 8],
    ) {
        let mut h = [_mm256_setzero_si256(); 8];
        for i in 0..8 {
            h[i] = _mm256_set1_epi32(key[i] as i32);
        }
        let mut lo = [0i32; 8];
        let mut hi = [0i32; 8];
        for i in 0..8 {
            let c = if increment_counter { counter.wrapping_add(i as u64) } else { counter };
            lo[i] = c as u32 as i32;
            hi[i] = (c >> 32) as u32 as i32;
        }
        let counter_lo = _mm256_loadu_si256(lo.as_ptr() as *const __m256i);
        let counter_hi = _mm256_loadu_si256(hi.as_ptr() as *const __m256i);
        let block_len = _mm256_set1_epi32(64);
        let iv0 = _mm256_set1_epi32(IV[0] as i32);
        let iv1 = _mm256_set1_epi32(IV[1] as i32);
        let iv2 = _mm256_set1_epi32(IV[2] as i32);
        let iv3 = _mm256_set1_epi32(IV[3] as i32);

        for b in 0..blocks {
            let mut f = flags;
            if b == 0 {
                f |= flags_start;
            }
            if b + 1 == blocks {
                f |= flags_end;
            }
            let mut m_lo = [_mm256_setzero_si256(); 8];
            let mut m_hi = [_mm256_setzero_si256(); 8];
            for lane in 0..8 {
                let p = base.add(lane * stride + b * 64);
                m_lo[lane] = _mm256_loadu_si256(p as *const __m256i);
                m_hi[lane] = _mm256_loadu_si256(p.add(32) as *const __m256i);
            }
            transpose(&mut m_lo);
            transpose(&mut m_hi);
            let m = [
                m_lo[0], m_lo[1], m_lo[2], m_lo[3], m_lo[4], m_lo[5], m_lo[6], m_lo[7], m_hi[0],
                m_hi[1], m_hi[2], m_hi[3], m_hi[4], m_hi[5], m_hi[6], m_hi[7],
            ];
            let mut v = [
                h[0],
                h[1],
                h[2],
                h[3],
                h[4],
                h[5],
                h[6],
                h[7],
                iv0,
                iv1,
                iv2,
                iv3,
                counter_lo,
                counter_hi,
                block_len,
                _mm256_set1_epi32(f as i32),
            ];
            round(&mut v, &m, 0);
            round(&mut v, &m, 1);
            round(&mut v, &m, 2);
            round(&mut v, &m, 3);
            round(&mut v, &m, 4);
            round(&mut v, &m, 5);
            round(&mut v, &m, 6);
            for i in 0..8 {
                h[i] = xor(v[i], v[i + 8]);
            }
        }
        transpose(&mut h);
        for lane in 0..8 {
            _mm256_storeu_si256(out[lane].as_mut_ptr() as *mut __m256i, h[lane]);
        }
    }
}
