/// Reduce `cvs[..n]` (n even) pairwise into parent CVs, in place. Returns n/2.
fn parent_cvs(cvs: &mut [[u32; 8]], n: usize, key: &[u32; 8], flags: u32) -> usize {
    let pairs = n / 2;
    let mut out = [[0u32; 8]; FLAT_CHUNKS / 2];
    let mut j = 0;
    #[cfg(target_arch = "x86_64")]
    {
        if use_avx2() {
            let mut tmp = [[0u32; 8]; 8];
            while j + 8 <= pairs {
                unsafe {
