fn is_printable(act: Act, b: u8) -> bool {
    (act == Act::Print && b != 0x7f)
        || act == Act::BeginUtf8
        || (act == Act::Execute && b.is_ascii_whitespace())
}

/// Number of bytes in a UTF-8 sequence, given its lead byte.
fn utf8_len(lead: u8) -> usize {
    match lead {
        0xc0..=0xdf => 2,
        0xe0..=0xef => 3,
        0xf0..=0xf7 => 4,
        _ => 1,
    }
}

/// Remove ANSI escape sequences and non-whitespace control characters in the
/// same way a stripping terminal adapter does, keeping printable text.
pub fn strip(input: &str) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    let mut bytes: &[u8] = input.as_bytes();
    let mut state = St::Ground;
    let mut utf8_remaining = 0usize;
    loop {
        // Phase 1: skip until something printable.
        let mut pos = bytes.len();
        for (i, &b) in bytes.iter().enumerate() {
            if state == St::Utf8 {
                pos = i;
                break;
            }
            let (ns, act) = state_change(state, b);
            if ns != St::Anywhere {
                state = ns;
            }
            if is_printable(act, b) {
                pos = i;
                break;
            }
        }
        bytes = &bytes[pos..];
        // Phase 2: take a run of printable bytes.
        let mut end = bytes.len();
        for (i, &b) in bytes.iter().enumerate() {
            if state == St::Utf8 {
                if utf8_remaining == 0 {
                    utf8_remaining = utf8_len(b);
                }
                utf8_remaining -= 1;
                if utf8_remaining == 0 {
                    state = St::Ground;
                }
                continue;
            }
            let (ns, act) = state_change(St::Ground, b);
            if ns != St::Anywhere {
                state = ns;
            }
            if state == St::Utf8 {
                utf8_remaining = utf8_len(b) - 1;
                if utf8_remaining == 0 {
                    state = St::Ground;
                }
                continue;
            }
            if !is_printable(act, b) {
                end = i;
                break;
            }
        }
        let (printable, rest) = bytes.split_at(end);
        bytes = rest;
        if printable.is_empty() {
            break;
        }
        out.extend_from_slice(printable);
    }
    String::from_utf8_lossy(&out).into_owned()
}

